<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\WebAuthn\Application\Usecase\FinishAuthentication;

use DateTimeImmutable;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\Gateway\WebAuthnChallengeGateway;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\Gateway\WebAuthnCredentialGateway;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\Exception\WebAuthnException;
use Civi\Lughauth\Features\OAuth\WebAuthn\Infrastructure\Service\WebAuthnVerifier;
use Civi\Lughauth\Shared\Exception\NotFoundException;

/**
 * Application use case that completes the WebAuthn authentication ceremony.
 *
 * Looks up the pending challenge by ID, validates that it is of type "authenticate"
 * and has not expired, then resolves the stored credential by the ID supplied in
 * the client assertion. The cryptographic assertion (authenticatorData + clientDataJSON
 * + signature) is delegated to WebAuthnVerifier, which performs origin binding,
 * RP ID hash verification, and replay-attack detection via the sign counter. On
 * success, the sign count is updated in the credential store, the challenge is marked
 * verified, and the authenticated user's UID and username are returned to the caller
 * for use in the subsequent OIDC token-issuance flow.
 */
final class FinishAuthenticationUsecase
{
    public function __construct(
        private readonly TenantReadGateway $tenants,
        private readonly WebAuthnChallengeGateway $challengeGateway,
        private readonly WebAuthnCredentialGateway $credentialGateway,
        private readonly WebAuthnVerifier $verifier,
    ) {
    }

    /**
     * Verifies the WebAuthn assertion and marks the challenge as verified.
     * Returns ['userUid', 'username'] for the authenticated user.
     */
    public function finish(
        string $challengeId,
        string $tenantName,
        array $clientCredential,
        string $origin,
        string $rpId,
    ): array {
        $tenant = $this->tenants->findOneByName($tenantName);
        if (!$tenant) {
            throw new NotFoundException('tenant ' . $tenantName);
        }
        $tenantId = $tenant->uid() ?? $tenantName;

        $challenge = $this->challengeGateway->findById($challengeId, $tenantId);
        if (!$challenge) {
            throw WebAuthnException::challengeNotFound();
        }
        if ($challenge->isExpired()) {
            throw WebAuthnException::challengeExpired();
        }
        if ($challenge->type !== 'authenticate') {
            throw WebAuthnException::verificationFailed('wrong challenge type');
        }

        $credentialId = $clientCredential['id'] ?? '';
        $storedCredential = $this->credentialGateway->findByCredentialId($credentialId, $tenantId);
        if (!$storedCredential) {
            throw WebAuthnException::credentialNotFound();
        }
        if (!$storedCredential->enabled) {
            throw WebAuthnException::credentialDisabled();
        }

        $newSignCount = $this->verifier->verifyAssertion(
            $clientCredential,
            $challenge->challenge,
            $origin,
            $rpId,
            $storedCredential->publicKey,
            $storedCredential->signCount,
        );

        $now = new DateTimeImmutable();
        $this->credentialGateway->updateSignCount($credentialId, $tenantId, $newSignCount, $now);

        $verified = $challenge->markVerified($storedCredential->userUid, $storedCredential->username);
        $this->challengeGateway->markVerified($verified);

        return [
            'userUid' => $storedCredential->userUid,
            'username' => $storedCredential->username,
        ];
    }
}
